'use strict';
const pack=window.RETH_PACK;
const steps=pack.steps;
const catalog=Object.fromEntries([...steps,...pack.details].map(s=>[s.id,s]));
const KEY='reading-studio-reth-'+pack.commit.slice(0,12)+'-v2';
const presenting=new URLSearchParams(location.search).has('present');
let persisted={};try{persisted=JSON.parse(localStorage.getItem(presenting?KEY+'-public':KEY)||'{}')}catch{}
let state={pos:0,order:steps.map(s=>s.id),selected:null,tab:'explain',nav:'tour',detour:null,expanded:[],focus:true,font:13,notes:{},reviewed:{},questions:[],experience:'TypeScript',...persisted};
state.order=Array.isArray(state.order)?state.order.filter(id=>catalog[id]):steps.map(s=>s.id);
if(!state.order.length)state.order=steps.map(s=>s.id);
state.pos=Math.max(0,Math.min(state.order.length-1,Number(state.pos)||0));
if(state.detour&&!catalog[state.detour.id])state.detour=null;
state.expanded=Array.isArray(state.expanded)?state.expanded:[];
state.questions=Array.isArray(state.questions)?state.questions:[];
state.notes=state.notes&&typeof state.notes==='object'?state.notes:{};
state.reviewed=state.reviewed&&typeof state.reviewed==='object'?state.reviewed:{};
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>catalog[state.detour?.id||state.order[state.pos]];
let channel;try{channel=new BroadcastChannel('reth-reading-'+pack.commit)}catch{}
function snapshot(){return {pos:state.pos,order:[...state.order],selected:state.selected,detour:state.detour?{id:state.detour.id}:null,expanded:[...state.expanded],focus:state.focus,font:state.font}}
function save(){if(presenting)return;try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(KEY+'-public',JSON.stringify(snapshot()));$('saved').textContent='✓ 保存済み'}catch{$('saved').textContent='保存できませんでした'}channel?.postMessage(snapshot())}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function highlight(line){return line.split(/(\/\/.*$|"(?:[^"\\]|\\.)*"|\b(?:pub|async|fn|let|mut|self|Self|impl|Future|Result|Ok|Err|Some|None|if|else|return|match|move|await|where|for|in|type|use|const|struct|trait)\b)/g).map(t=>/^\/\//.test(t)?`<span class="comment">${esc(t)}</span>`:/^"/.test(t)?`<span class="str">${esc(t)}</span>`:/^(pub|async|fn|let|mut|self|Self|impl|Future|Result|Ok|Err|Some|None|if|else|return|match|move|await|where|for|in|type|use|const|struct|trait)$/.test(t)?`<span class="kw">${t}</span>`:esc(t)).join('')}
function navigate(pos){state.pos=pos;state.detour=null;state.selected=null;state.expanded=[];render(true);save()}
function goId(id){const pos=state.order.indexOf(id);if(pos>=0)navigate(pos);else detour(id)}
function nav(){document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===state.nav));if(state.nav==='tour'){
$('navigation').innerHTML=state.order.map((id,i)=>{const s=catalog[id];return `<div class="tour-row"><button class="tour-step ${!state.detour&&state.pos===i?'active':''}" data-step="${i}"><span class="step-num">${String(i+1).padStart(2,'0')}</span><span><b>${esc(s.title)}</b><small>${esc(s.short)}</small></span></button>${i>=steps.length?`<button class="remove-step" data-remove-step="${i}" aria-label="追加ステップを削除">×</button>`:''}</div>`}).join('');
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>navigate(+b.dataset.step));document.querySelectorAll('[data-remove-step]').forEach(b=>b.onclick=()=>{const n=+b.dataset.removeStep;state.order.splice(n,1);if(n<state.pos)state.pos--;state.pos=Math.min(state.pos,state.order.length-1);render();save()});
}else{
$('navigation').innerHTML='<input class="search" aria-label="コードを検索" placeholder="⌕ ファイル・シンボルを検索"><div id="file-list"></div>';
function files(q=''){$('file-list').innerHTML=Object.values(catalog).filter(s=>(s.path+' '+s.symbol+' '+s.title).toLowerCase().includes(q.toLowerCase())).map(s=>`<button class="file-entry ${s.id===current().id?'active':''}" data-file="${s.id}"><b>${esc(s.symbol)}</b><small>${esc(s.path)}:${s.start}</small></button>`).join('')||'<p class="muted">該当するコードはありません</p>';document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>goId(b.dataset.file))}files();document.querySelector('.search').oninput=e=>files(e.target.value);
}}
function renderCode(scroll=false){const s=current();const range=state.selected?[state.selected,state.selected]:s.lines;const lines=s.code.split('\n');let html='';
for(let i=0;i<lines.length;i++){const n=s.start+i;const fold=(s.folds||[]).find(([a,b])=>n===a&&!state.expanded.includes(a));if(fold){html+=`<button class="fold-row" data-expand="${fold[0]}">＋ ${fold[1]-fold[0]+1} 行を折りたたみ（L${fold[0]}–L${fold[1]}）· 展開</button>`;i=fold[1]-s.start;continue}const active=n>=range[0]&&n<=range[1];html+=`<button class="code-line ${active?'hl':state.focus?'dim':''}" data-line="${n}" aria-label="${n}行目"><span class="ln">${n}</span><span class="line-text">${highlight(lines[i])||' '}</span></button>`}
$('code').innerHTML=html;document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.line;renderCode();insight();save()});document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{state.expanded.push(+b.dataset.expand);renderCode();save()});$('range').textContent=`L${range[0]}–L${range[1]} · ${pack.commit.slice(0,12)}`;
if(scroll){const row=document.querySelector('#code .hl');if(row)$('code').scrollTop=Math.max(0,row.offsetTop-70)}
}
function render(scroll=false){const s=current();document.body.dataset.readingStep=s.id;document.dispatchEvent?.(new Event('reading-context-change'));$('crumb').textContent=s.title;$('step-label').textContent=state.detour?'SIDE EXPLORATION':`STEP ${String(state.pos+1).padStart(2,'0')} / ${String(state.order.length).padStart(2,'0')}`;$('title').textContent=s.question;$('subtitle').textContent=s.subtitle;$('filename').textContent=s.path;$('filename').title=s.path;$('symbol').textContent=s.symbol;$('source-link').href=s.sourceUrl;$('detour').hidden=!state.detour;$('prev').disabled=!state.detour&&state.pos===0;$('next').disabled=!state.detour&&state.pos===state.order.length-1;$('focus').classList.toggle('selected',state.focus);document.documentElement.style.setProperty('--code-size',state.font+'px');renderCode(scroll);renderMap();$('progress').textContent=`${state.pos+1} / ${state.order.length} ステップ · ${Object.values(state.reviewed).filter(Boolean).length} 件確認済み`;$('experience').value=state.experience;$('related').textContent=state.detour?'↶ 本筋へ戻る':'↗ '+catalog[s.related||'rpc-contract'].title;nav();insight();}
function renderMap(){const active=steps.findIndex(s=>s.id===current().id);const from=Math.max(0,Math.min(steps.length-4,active-1));const visible=steps.slice(from,from+4);
$('flow').innerHTML=(from>0?'<button class="map-more" data-jump="0" aria-label="最初のステップ">←</button>':'')+visible.map((s,i)=>`${i?`<button class="arrow ${visible[i-1].id==='queue'?'async-edge':''}" data-edge="${from+i-1}" aria-label="${esc(visible[i-1].edge)}の根拠">${visible[i-1].id==='queue'?'⋯':'→'}</button>`:''}<button class="flow-node ${current().id===s.id?'active':''}" data-node="${s.id}"><small>${String(from+i+1).padStart(2,'0')} &nbsp; ${s.group}</small><b>${s.node}</b><code>${esc(s.symbol)}</code></button>`).join('')+(from+4<steps.length?`<button class="map-more" data-jump="${steps.length-1}" aria-label="最後のステップ">→</button>`:'');document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>goId(b.dataset.node));document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>goId(steps[+b.dataset.jump].id));document.querySelectorAll('[data-edge]').forEach(b=>b.onclick=()=>edge(+b.dataset.edge))}
function edge(i){const s=steps[i],next=steps[i+1];const anchor=s.sourceUrl.replace(/#L.*$/,`#L${s.edgeLine}`);$('edge-content').innerHTML=`<div class="eyebrow">関係の根拠 · 静的読解</div><h3>${esc(s.node)} → ${esc(next.node)}</h3><p>${esc(s.edge)}</p><p>${i===3?'直接の関数呼び出しではありません。要求チャネルへの送信と、BatchTxProcessor::poll での受信を介する関係です。':i===4?'件数と origin に応じて呼び出す API が変わります。図はこれらの分岐を一つにまとめています。':'該当行の呼び出し式を根拠にしています。実行観測ではありません。'}</p><a href="${anchor}" target="_blank" rel="noopener">送信・呼び出し箇所 L${s.edgeLine} ↗</a>${i===3?`<p><a href="${catalog['batch-runner'].sourceUrl}" target="_blank" rel="noopener">受信側の poll 実装 ↗</a></p>`:''}`;$('evidence-dialog').showModal()}
function insight(){const s=current();document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));$('note-count').textContent=state.questions.length||'';const box=$('insight-content');
if(state.tab==='explain'){
box.innerHTML=`<div class="card-eyebrow">✧ READING LENS <span class="pill">AI事前作成</span></div><h3>${esc(s.summary)}</h3><p>${esc(s.detail)}</p>${state.selected?`<div class="selected-info">L${state.selected} を選択中 · 解説はこの節全体に対応</div>`:''}<div class="io"><b>入力</b><span>${esc(s.input)}</span></div><div class="io"><b>出力</b><span>${esc(s.output)}</span></div><div class="io"><b>副作用</b><span>${esc(s.side)}</span></div><div class="evidence"><p>分岐と読解の境界</p><p>${esc(s.branch)}</p><button id="evidence">↗ 注目範囲 L${s.lines[0]}–L${s.lines[1]} を表示</button></div><div class="truth-tags"><span>根拠：原文の静的読解</span><span>版：コミット固定</span></div><button id="review" class="review">${state.reviewed[s.id]?'✓ 人間の確認済み · 取り消す':'○ 原文を確認済みにする'}</button>`;
$('review').onclick=()=>{state.reviewed[s.id]=!state.reviewed[s.id];render();save()};$('evidence').onclick=()=>{state.selected=null;state.focus=true;renderCode(true);insight();save()};
}else if(state.tab==='language'){
const comparison=state.experience==='TypeScript'?s.compare:state.experience==='Python'?'Python の async/await や例外処理との違いに注目しましょう。Rust は所有権・借用を持ち、失敗を Result という値で明示的に返します。':'まず入力・出力・失敗する条件を押さえ、この構文が注目範囲のどこにあるかを確認しましょう。';
box.innerHTML=`<div class="card-eyebrow">Aa LANGUAGE BRIDGE <span class="pill">Rust の知識</span></div><h3>構文から、処理を理解する。</h3><div class="language-card"><code>${esc(s.concept)}</code><p>${esc(s.language)}</p></div><div class="small-title">${esc(state.experience)} からの橋渡し</div><p>${esc(comparison)}</p><a class="doc-link" href="${s.doc}" target="_blank" rel="noopener">言語・ライブラリの公式資料 ↗</a><div class="evidence"><p>Reth 固有の型・処理と区別する</p><p>TransactionOrigin やプールの挙動はプロジェクト固有です。言語仕様だけから意味を決めず、元コードを確認します。</p></div><button id="show-code" class="review">対応するコードを強調する</button>`;$('show-code').onclick=()=>{state.selected=null;state.focus=true;renderCode(true);save()};
}else{
box.innerHTML=`<div class="card-eyebrow">SESSION NOTEBOOK <span class="pill">手元だけに表示</span></div><h3>気づきを、次の説明へ。</h3><textarea id="note" aria-label="発表者メモ" placeholder="このステップで伝えたいこと…">${esc(state.notes[s.id]||'')}</textarea><p>ブラウザーに自動保存。共有画面へは送信しません。</p><div class="small-title">未解決の問い</div><div id="questions">${state.questions.map((q,i)=>`<div class="question">${esc(q)} <button data-remove="${i}" aria-label="疑問を解決済みにする">✓ 解決</button></div>`).join('')||'<p>例：nonce が飛んだ場合はどのサブプールへ？</p>'}</div><textarea id="new-question" aria-label="新しい疑問" style="min-height:65px" placeholder="次に確かめたいこと…"></textarea><button id="question-add" class="review">＋ 疑問を記録する</button>`;
$('note').oninput=e=>{state.notes[s.id]=e.target.value;save()};$('question-add').onclick=()=>{const q=$('new-question').value.trim();if(!q)return;state.questions.push(q);save();insight()};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.questions.splice(+b.dataset.remove,1);save();insight()});
}}
function detour(id){if(!catalog[id])return;const origin=state.detour?.origin||{selected:state.selected,tab:state.tab,expanded:[...state.expanded],scroll:$('code').scrollTop};state.detour={id,origin};state.selected=null;state.expanded=[];state.tab='explain';render(true);save()}
function back(){if(!state.detour)return;const d=state.detour.origin||{};state.detour=null;state.selected=d.selected??null;state.tab=d.tab||'explain';state.expanded=d.expanded||[];render();$('code').scrollTop=d.scroll||0;save()}
$('prev').onclick=()=>state.detour?back():navigate(Math.max(0,state.pos-1));$('next').onclick=()=>state.detour?back():navigate(Math.min(state.order.length-1,state.pos+1));$('back').onclick=back;$('related').onclick=()=>state.detour?back():detour(current().related||'rpc-contract');$('close-dialog').onclick=()=>$('evidence-dialog').close();
$('focus').onclick=()=>{state.focus=!state.focus;renderCode();$('focus').classList.toggle('selected',state.focus);save()};$('fontup').onclick=()=>{state.font=Math.min(22,state.font+1);render();save()};$('fontdown').onclick=()=>{state.font=Math.max(11,state.font-1);render();save()};
$('add').onclick=()=>{state.order.push(current().id);nav();save();toast('現在のコードを説明順の末尾に追加しました')};$('experience').onchange=e=>{state.experience=e.target.value;insight();save()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;insight();save()});document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.nav=b.dataset.nav;nav();save()});
$('export').onclick=()=>{const output={schemaVersion:2,kind:'source-reading-pack',...pack,session:state};const blob=new Blob([JSON.stringify(output,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='reth-reading-pack-'+pack.commit.slice(0,12)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Reading Pack を書き出しました（コード抜粋・メモを含みます）')};
$('present').onclick=()=>{if(presenting){location.href=location.pathname;return}save();const w=window.open(location.pathname+'?present=1','reth-presentation');if(!w)toast('ポップアップを許可すると共有画面を開けます')};
if(presenting){document.body.classList.add('presenting');$('present').textContent='探索画面に戻る';state.notes={};state.questions=[];state.reviewed={};state.tab='explain';if(channel)channel.onmessage=e=>{const d=e.data;if(!d||d.request)return;const order=Array.isArray(d.order)?d.order.filter(id=>catalog[id]):[];if(!order.length)return;state.order=order;state.pos=Math.max(0,Math.min(order.length-1,Number(d.pos)||0));state.detour=d.detour&&catalog[d.detour.id]?{id:d.detour.id}:null;state.selected=Number.isInteger(d.selected)?d.selected:null;state.expanded=Array.isArray(d.expanded)?d.expanded.filter(Number.isInteger):[];state.focus=!!d.focus;state.font=Math.max(11,Math.min(22,Number(d.font)||13));render(true)};channel?.postMessage({request:true})}else if(channel){channel.onmessage=e=>{if(e.data?.request)channel.postMessage(snapshot())}}
document.addEventListener('keydown',e=>{if(['TEXTAREA','INPUT','SELECT'].includes(e.target.tagName))return;if($('evidence-dialog').open)return;if(e.key==='Escape')back();if(e.key==='ArrowRight'&&!state.detour&&state.pos<state.order.length-1)navigate(state.pos+1);if(e.key==='ArrowLeft'&&!state.detour&&state.pos>0)navigate(state.pos-1)});
const linkedStep=new URLSearchParams(location.search).get('step');
if(!presenting&&catalog[linkedStep]){const linkedPos=state.order.indexOf(linkedStep);if(linkedPos>=0){state.pos=linkedPos;state.detour=null}else{state.detour={id:linkedStep,origin:{selected:null,tab:'explain',expanded:[],scroll:0}}}state.selected=null;state.expanded=[];}
render();

const processOrigin=new URLSearchParams(location.search).get('from');if(processOrigin&&(processOrigin.startsWith('zoom.html?')||processOrigin.startsWith('lenses.html#'))&&$('return-process'))$('return-process').href=processOrigin;
